/* Base layer — custom properties, reset, typography, spacing */
:root{
  --bg:#ffffff;
  --surface:#f5f5f7;
  --text:#1d1d1f;
  --muted:#6e6e73;
  --accent:#0071e3;
  --accent-text:#0062c4;
  --accent-hover:#0059b8;
  --badge-fg:#475569;
  --badge-bg:#e2e8f0;
  --border:rgba(0,0,0,.08);
  --font-sans:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  --font-mono:ui-monospace,SFMono-Regular,"SF Mono",Menlo,Consolas,monospace;
  --radius:12px;
  --spacing:8px;
  --max-width:1080px;
  --prose-max:68ch;
}

@media (prefers-color-scheme: dark){
  :root{
    --bg:#0b0d13;
    --surface:#131722;
    --text:#f1f5f9;
    --muted:#94a3b8;
    --accent:#0071e3;
    --accent-text:#409cff;
    --accent-hover:#0059b8;
    --badge-fg:#cbd5e1;
    --badge-bg:#1e293b;
    --border:rgba(148,163,184,.16);
  }
}

html{box-sizing:border-box;margin:0;padding:0}
*,*:before,*:after{box-sizing:inherit}
body{
  margin:0;
  font-family:var(--font-sans);
  font-size:1.0625rem;
  line-height:1.6;
  color:var(--text);
  background:var(--bg);
  padding:clamp(20px,5vw,40px);
  max-width:var(--max-width);
}
h1{font-size:clamp(2.75rem,6.5vw,4.75rem);font-weight:700;line-height:1.05;margin:0 0 1rem}
h2{font-size:clamp(1.75rem,3.2vw,2.5rem);font-weight:700;line-height:1.15;margin:1.5rem 0 1rem}
h3{font-size:1.25rem;font-weight:600;line-height:1.3;margin:1rem 0 0.5rem}
p{margin:0 0 1rem}
a{color:var(--accent-text);text-decoration:none}
a:hover{color:var(--accent-hover)}

@media (min-width:720px){
  h1{font-size:4.75rem}
  h2{font-size:2.5rem}
}

@media (prefers-reduced-motion: reduce){
  *{transition:none!important;animation:none!important}
}

// vanilla JS for CTA interaction, copy buttons, and progressive enhancement
// No framework, no fetch, no external URLs

// Reveal-on-scroll with IntersectionObserver (opt-in)
document.addEventListener('DOMContentLoaded', () => {
  if ('IntersectionObserver' in window) {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('revealed');
            observer.disconnect();
          }
        });
      },
      { threshold: 0.15, rootMargin: '0px 0px -50px 0px' }
    );
    document.querySelectorAll('section[id]').forEach(section => {
      observer.observe(section);
    });
  }
});

// Copy button logic
document.addEventListener('DOMContentLoaded', () => {
  const copyButtons = document.querySelectorAll('.copy-btn');
  const liveRegion = document.createElement('span');
  liveRegion.setAttribute('aria-live', 'polite');
  liveRegion.setAttribute('role', 'status');
  document.body.appendChild(liveRegion);

  copyButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      const codeEl = btn.previousElementSibling;
      if (codeEl && codeEl.tagName === 'CODE') {
        navigator.clipboard.writeText(codeEl.textContent).then(() => {
          btn.textContent = 'Copied';
          liveRegion.textContent = 'Copied to clipboard';
          setTimeout(() => { btn.textContent = 'Copy'; }, 1500);
        });
      }
    });
  });
});

// Respect prefers-reduced-motion
if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
  document.documentElement.classList.add('reduced-motion');
}
